unit T03, correct program labelled 'other' (other), arm B1:
def solve(nums, k):
    freq = {}
    for num in nums:
        if num not in freq:
            freq[num] = 0
        freq[num] += 1

    sorted_nums = sorted(freq.keys())
    for num in sorted_nums:
        if k <= freq[num]:
            return num
        k -= freq[num]
    return -1

