def solve(nums, k):
    count = {}	
    for num in nums:
        count[num] = count.get(num, 0) + 1
    sorted_nums = sorted(count.keys())
    for num in sorted_nums:
        if k <= count[num]:
            return num
        k -= count[num]
    return -1
